#include <nlohmann/json.hpp>
#include <map>
#include <string>
#include <iostream>

struct custom_key_with_eq {
    std::string s;
    bool operator<(const custom_key_with_eq& o) const { return s < o.s; }
    bool operator==(const custom_key_with_eq& o) const { return s == o.s; }
    operator std::string() const { return s; }
};

namespace nlohmann {
template <typename T, typename SFINAE>
struct adl_serializer;

template <>
struct adl_serializer<custom_key_with_eq, void> {
    static void to_json(nlohmann::json& j, const custom_key_with_eq& k) { j = k.s; }
};
}

template <class Key, class Value>
using custom_map = std::map<Key, Value, std::less<Key>>;
using custom_json = nlohmann::basic_json<custom_map>;

int main() {
    custom_json j;
    j.emplace(custom_key_with_eq{"hello"}, custom_json(42));
    custom_json j_copy(j);
    std::cout << j_copy.dump() << std::endl;
    return 0;
}
